(()=>{'use strict';const d=JSON.parse(document.querySelector('#yg-supplement-data').textContent);const buttons=[...document.querySelectorAll('[data-yg-step]')];function show(i){buttons.forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.ygStep)===i)));document.querySelector('#yg-flow-title').textContent=d.flow[i].title;document.querySelector('#yg-flow-body').textContent=d.flow[i].body;}buttons.forEach(b=>b.addEventListener('click',()=>show(Number(b.dataset.ygStep))));show(0);})();
